namespace Ashfall.Integration.Playable.HandsWeapons
{
    public sealed partial class R23HandsWeapons
    {
        readonly Dictionary<int,R24BladeArt> bladeArt=new Dictionary<int,R24BladeArt>();R24ItemAudio bladeAudio;AudioSource bladeWhoosh,bladeHum,bladeRaise;bool bladeReady;Mesh bladeCue;
        public bool BladesReady{get{return bladeReady;}}public bool KatanaGuardActive{get{return KnifeUsable&&round!=null&&round.Melee!=null&&round.Melee.ShieldActive;}}public bool MeleeSupported{get{return KnifeUsable&&round!=null&&round.Melee!=null&&round.Melee.Supported;}}
        public bool MeleeTrailVisible{get{R24BladeArt art;return bladeArt.TryGetValue(selectedWeapon,out art)&&art.TrailVisible;}}
        IEnumerator LoadBladePresentation(){bladeCue=R24BladeArt.SourceCue();for(int i=18;i<21;i++){yield return visuals.Load(weaponIds[i],weaponModels[i]);foreach(var renderer in weaponModels[i].GetComponentsInChildren<Renderer>(true))renderer.shadowCastingMode=ShadowCastingMode.Off;bladeArt.Add(i,new R24BladeArt(weaponIds[i],weaponModels[i],bladeCue));}bladeAudio=new R24ItemAudio();bladeAudio.SetVolume(sfxVolume);yield return bladeAudio.Load("blade-swing","katana-shield","katana-raise");bladeWhoosh=bladeAudio.Voice(weapon,"Source physical sword swing",-13,15);bladeHum=bladeAudio.Voice(weapon,"Source katana shield sustain",-7,18,true);bladeRaise=bladeAudio.Voice(weapon,"Source katana shield raise",-7,15);bladeReady=true;}
        bool BladeTransient(int index,Transform item){R24BladeArt art;return bladeArt.TryGetValue(index,out art)&&art.IsTransient(item);}
        void UpdateBladeSupport(bool usable){if(round==null||round.Melee==null)return;var support=haveInputSnapshot?lastInput.Hand(1-primaryHand):new R23HandInput(false,false,0,0);float distance=Vector3.Distance(SupportTransform.position,weapon.TransformPoint(From(R24MeleeRuntime.SupportPoint)));round.Melee.UpdateSupport(usable,support.Tracked,support.Reserved,support.GripHeld,distance);if(round.Melee.SupportAcquired)Pulse(1-primaryHand,.3f,.04f);}
        void SyncBladePresentation(){bool usable=KnifeUsable;foreach(var pair in bladeArt){if(pair.Key==selectedWeapon&&usable)pair.Value.Present(round.Melee,true);else pair.Value.Hide();}bool shield=usable&&round!=null&&round.Melee!=null&&round.Melee.ShieldActive;if(shield&&bladeHum!=null&&!bladeHum.isPlaying){bladeAudio.Play(bladeHum,"katana-shield");bladeAudio.Play(bladeRaise,"katana-raise");}if(!shield){if(bladeHum!=null)bladeHum.Stop();if(bladeRaise!=null)bladeRaise.Stop();}if(!usable&&bladeWhoosh!=null)bladeWhoosh.Stop();}
        void SampleBladeArt(float dt,bool usable){R24BladeArt art;if(!bladeArt.TryGetValue(selectedWeapon,out art)||round.Melee==null)return;var owner=round.Melee;art.SampleBlade(weapon.TransformPoint(From(owner.BladeBasePoint)),weapon.TransformPoint(From(owner.BladeTipPoint)),dt,usable,player);}
        void PlayBladeWhoosh(R24MeleeRuntime owner){if(!owner.WhooshRequested)return;var voice=owner.Profile.Id=="knife"?knifeWhoosh:bladeWhoosh;var audio=owner.Profile.Id=="knife"?knifeAudio:bladeAudio;if(voice!=null&&audio!=null){voice.pitch=owner.WhooshPitch;audio.Play(voice,owner.Profile.Id=="knife"?"knife-swing":"blade-swing");}}
        // Only a real incoming bullet caller should use this. Area/melee/environment damage bypasses the source finite front guard.
        public bool TryInterceptMeleeBullet(Vector3 origin,Vector3 endpoint,out Vector3 point){point=Vector3.zero;if(!To(origin).IsFinite||!To(endpoint).IsFinite||!KnifeUsable||round==null||round.Melee==null)return false;UpdateBladeSupport(KnifeUsable);var q=weapon.rotation;var pose=new R23ShotPose(To(weapon.position),To(q*Vector3.right),To(q*Vector3.up),To(q*Vector3.forward));BulletGuard guard;float fraction;if(!round.Melee.TryReadBulletGuard(pose,KnifeUsable,out guard)||!guard.Intersects(To(origin),To(endpoint),out fraction))return false;point=Vector3.Lerp(origin,endpoint,fraction);Pulse(primaryHand,.16f,.025f);Pulse(1-primaryHand,.2f,.025f);return true;}
